using System;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine.UI;
using TMPro;
namespace LWS.TruckSports.Editor {
public static class SportsBroadcastAuthoring {
 const string Folder="Assets/TruckSports/UI";
 public static SportsBroadcastTheme Theme(){SportsPortraitAuthoring.Create();Directory.CreateDirectory(Folder);Directory.CreateDirectory("Assets/TruckSports/Resources");AssetDatabase.Refresh();var path="Assets/TruckSports/Resources/SportsBroadcastTheme.asset";var theme=AssetDatabase.LoadAssetAtPath<SportsBroadcastTheme>(path);if(theme==null){theme=ScriptableObject.CreateInstance<SportsBroadcastTheme>();AssetDatabase.CreateAsset(theme,path);}theme.headingFont=Font("RobotoCondensed-Bold SDF","Broadcast condensed heading");theme.bodyFont=Font("RobotoCondensed-Regular SDF","Broadcast readable body");theme.controllerGlyph=AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Heat - Complete Modern UI/Textures/Controllers/Xbox/Xbox Controller.png");theme.leftStickGlyph=AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Heat - Complete Modern UI/Textures/Controllers/Xbox/Xbox Left Stick.png");theme.rightStickGlyph=AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Heat - Complete Modern UI/Textures/Controllers/Xbox/Xbox Right Stick.png");EditorUtility.SetDirty(theme);return theme;}
 static TMP_FontAsset Font(string source,string name){string path=Folder+"/"+name+".asset";var font=AssetDatabase.LoadAssetAtPath<TMP_FontAsset>(path);if(font==null){var original=AssetDatabase.LoadAssetAtPath<TMP_FontAsset>("Assets/Heat - Complete Modern UI/Fonts/"+source+".asset");if(original==null)throw new Exception("Installed Heat font missing "+source);font=UnityEngine.Object.Instantiate(original);font.name=name;font.fallbackFontAssetTable=new System.Collections.Generic.List<TMP_FontAsset>{TMP_Settings.defaultFontAsset};AssetDatabase.CreateAsset(font,path);}return font;}
 public static void ApplyScene(SportsBroadcastTheme theme=null){if(theme==null)theme=Theme();foreach(var label in UnityEngine.Object.FindObjectsByType<SportsPerCameraBillboard>(FindObjectsInactive.Include)){label.maximumPixelWidth=144;label.maximumPixelHeight=24;EditorUtility.SetDirty(label);}foreach(var canvas in UnityEngine.Object.FindObjectsByType<Canvas>(FindObjectsInactive.Include)){bool sports=canvas.GetComponents<MonoBehaviour>().Any(c=>c!=null&&c.GetType().Namespace!=null&&c.GetType().Namespace.StartsWith("LWS.Truck"));if(!sports)continue;var style=canvas.GetComponent<SportsBroadcastCanvas>();if(style==null)style=canvas.gameObject.AddComponent<SportsBroadcastCanvas>();style.headingFont=theme.headingFont;style.bodyFont=theme.bodyFont;style.eventMenus=canvas.GetComponent<SportsEventMenus>();style.Apply();foreach(var component in canvas.GetComponents<MonoBehaviour>()){if(component==null||component.GetType().Namespace==null||!component.GetType().Namespace.StartsWith("LWS.Truck"))continue;var field=component.GetType().GetField("pages");if(field==null||field.FieldType!=typeof(GameObject[]))continue;foreach(var page in (GameObject[])field.GetValue(component))if(page!=null){var group=page.GetComponent<CanvasGroup>();if(group==null)group=page.AddComponent<CanvasGroup>();group.alpha=1;if(page.GetComponent<SportsBroadcastPage>()==null)page.AddComponent<SportsBroadcastPage>();}}EditorUtility.SetDirty(style);}}
 public static void UpgradeAll(){if(EditorApplication.isPlaying||EditorApplication.isCompiling||EditorUtility.scriptCompilationFailed)throw new Exception("Stopped compiled Editor required");var theme=Theme();int scenes=0;foreach(var path in SportsBuilder.SceneList()){var scene=EditorSceneManager.OpenScene(path);ApplyScene(theme);EditorSceneManager.SaveScene(scene);scenes++;}AssetDatabase.SaveAssets();File.WriteAllText("Logs/TruckSports/SevenSports/broadcast-saved-result.txt","PASS shared saved theme applied to "+scenes+" explicit Sports scenes. No scene physics, arena dimensions or vendor source modified.");}
 public static void Validate(){foreach(var path in SportsBuilder.SceneList()){var scene=EditorSceneManager.OpenScene(path);foreach(var canvas in scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<SportsBroadcastCanvas>(true))){if(canvas.headingFont==null||canvas.bodyFont==null||canvas.GetComponent<CanvasScaler>().screenMatchMode!=CanvasScaler.ScreenMatchMode.Expand)throw new Exception("Broadcast references/layout missing "+path);}}Debug.Log("SPORTS_BROADCAST_SAVED_VALIDATED");}
}
}
